"use client";

import { topCostJobs, dailyCostTrend } from "@/lib/mock-data";
import { Card, CardHeader, CardTitle } from "@/components/ui/card";

/* ── Donut Chart (SVG mock) ──────────────────────────────────────────────── */
function DonutChart() {
  const total = topCostJobs.reduce((s, j) => s + j.cost, 0);
  const radius = 60;
  const circumference = 2 * Math.PI * radius;
  let offset = 0;

  return (
    <div className="flex items-center gap-8">
      {/* SVG Donut */}
      <div className="relative flex-shrink-0">
        <svg width="160" height="160" viewBox="0 0 160 160">
          {topCostJobs.map((job) => {
            const pct = job.cost / total;
            const dashLen = pct * circumference;
            const dashOffset = -offset;
            offset += dashLen;
            return (
              <circle
                key={job.name}
                cx="80"
                cy="80"
                r={radius}
                fill="none"
                stroke={job.color}
                strokeWidth="20"
                strokeDasharray={`${dashLen} ${circumference - dashLen}`}
                strokeDashoffset={dashOffset}
                transform="rotate(-90 80 80)"
                className="transition-all duration-500"
              />
            );
          })}
          {/* Center label */}
          <text
            x="80"
            y="76"
            textAnchor="middle"
            className="fill-text-primary text-lg font-semibold"
            style={{ fontSize: "18px" }}
          >
            ${total.toFixed(2)}
          </text>
          <text
            x="80"
            y="94"
            textAnchor="middle"
            className="fill-text-secondary"
            style={{ fontSize: "11px" }}
          >
            total
          </text>
        </svg>
      </div>

      {/* Legend */}
      <div className="flex flex-col gap-2">
        {topCostJobs.map((job) => (
          <div key={job.name} className="flex items-center gap-2">
            <span
              className="h-2.5 w-2.5 rounded-full flex-shrink-0"
              style={{ backgroundColor: job.color }}
            />
            <span className="text-xs text-text-secondary font-mono">
              {job.name}
            </span>
            <span className="text-xs text-text-primary font-medium ml-auto pl-4">
              ${job.cost.toFixed(2)}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ── Bar Chart (styled divs) ────────────────────────────────────────────── */
function BarChart() {
  const max = Math.max(...dailyCostTrend.map((d) => d.cost));

  return (
    <div className="flex items-end gap-3 h-36">
      {dailyCostTrend.map((d) => (
        <div key={d.day} className="flex flex-1 flex-col items-center gap-1.5">
          <span className="text-[10px] text-text-secondary font-mono">
            ${d.cost.toFixed(2)}
          </span>
          <div className="w-full relative flex-1 flex items-end">
            <div
              className="w-full rounded-t-sm transition-all duration-500"
              style={{
                height: `${(d.cost / max) * 100}%`,
                background:
                  d.cost === max
                    ? "oklch(0.70 0.15 55)"
                    : "oklch(0.70 0.15 55 / 0.4)",
              }}
            />
          </div>
          <span className="text-[10px] text-text-secondary">{d.day}</span>
        </div>
      ))}
    </div>
  );
}

/* ── Exported Charts Component ───────────────────────────────────────────── */
export function Charts() {
  return (
    <div className="grid grid-cols-1 gap-3 lg:grid-cols-2">
      <Card>
        <CardHeader>
          <CardTitle>Top Cost Jobs</CardTitle>
        </CardHeader>
        <DonutChart />
      </Card>
      <Card>
        <CardHeader>
          <CardTitle>Daily Cost Trend</CardTitle>
        </CardHeader>
        <BarChart />
      </Card>
    </div>
  );
}
