"use client";

import { useState } from "react";
import { systemLogs } from "@/lib/mock-data";
import { cn } from "@/lib/utils";

const lineCounts = [100, 200, 500, 1000] as const;

export function SystemLogs() {
  const [lineCount, setLineCount] = useState<number>(100);

  return (
    <div className="rounded-lg border border-border bg-surface overflow-hidden flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2.5 border-b border-border">
        <h3 className="text-sm font-medium text-text-secondary">
          System Logs
        </h3>
        <div className="flex items-center gap-1">
          {lineCounts.map((count) => (
            <button
              key={count}
              onClick={() => setLineCount(count)}
              className={cn(
                "px-2 py-0.5 rounded text-[11px] font-mono transition-colors cursor-pointer",
                count === lineCount
                  ? "bg-primary/15 text-primary"
                  : "text-text-secondary hover:text-text-primary hover:bg-surface-elevated"
              )}
            >
              {count >= 1000 ? `${count / 1000}K` : count}
            </button>
          ))}
        </div>
      </div>

      {/* Log viewer */}
      <div
        className="flex-1 overflow-auto p-3 font-mono text-xs leading-relaxed"
        style={{ background: "oklch(0.12 0.01 250)" }}
      >
        {systemLogs.map((log, i) => (
          <div
            key={i}
            className="flex gap-3 py-0.5 hover:bg-white/[0.02] rounded px-1"
          >
            <span className="text-text-secondary/50 flex-shrink-0 select-none tabular-nums">
              {log.ts}
            </span>
            <span
              className={cn(
                "flex-shrink-0 w-12 text-right",
                log.level === "INFO" && "text-text-secondary",
                log.level === "WARN" && "text-warning",
                log.level === "ERROR" && "text-error"
              )}
            >
              {log.level}
            </span>
            <span
              className={cn(
                log.level === "ERROR" ? "text-error/80" : "text-text-primary/80"
              )}
            >
              {log.msg}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
